const app=document.getElementById('app');
const state={data:null,start:'',end:'',draftStart:'',draftEnd:'',editing:null,selected:new Set()};
const fmt=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:1}).format(Number(n||0));
const pct=n=>`${Math.round(Number(n||0))}%`;
const dte=s=>s?new Intl.DateTimeFormat('en-US',{dateStyle:'medium'}).format(new Date(s)):'—';
const initials=n=>(n||'V').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0].toUpperCase()).join('');
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const programsOf=s=>s==='Unmatched'?[]:String(s||'').split(',').map(x=>x.trim()).filter(Boolean);
function q(){const p=new URLSearchParams();if(state.start)p.set('start',state.start);if(state.end)p.set('end',state.end);return p.toString()?`?${p}`:''}
async function load(){try{const r=await fetch('/api/dashboard'+q(),{cache:'no-store'});const d=await r.json();if(!r.ok)throw Error(d.error||'Unable to load');state.data=d;render()}catch(e){app.innerHTML=`<div class="notice error">${esc(e.message)}</div>`}}
async function post(url,body){const r=await fetch(url,{method:'POST',headers:{'content-type':'application/json'},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d}
function rankRows(rows,kind){const sorted=[...rows].sort((a,b)=>metricValue(b,kind)-metricValue(a,kind));const max=kind==='impact'?(sorted[0]?.knownHours||1):100;return sorted.map((p,i)=>{const v=metricValue(p,kind),label=kind==='impact'?`${fmt(p.knownHours)} hrs`:pct(kind==='participation'?p.participationRate:p.crossSupportRate);let sub='';if(kind==='impact')sub=`${fmt(p.volunteerCredits)} volunteer equivalents`;else if(kind==='participation')sub=`${fmt(p.participatingCredits)} of ${fmt(p.eligibleCredits)} weighted caregiver equivalents participated`;else sub=`${fmt(p.crossSupportHours)} cross-program credited hours`;return `<div class="rankRow rank${i+1}"><div class="rankNo">${i===0?'🏆':'#'+(i+1)}</div><div class="rankMain"><div class="rankTop"><strong>${esc(p.name)}</strong><b>${label}</b></div><div class="rankBar"><i style="width:${Math.max(v>0?3:0,Math.min(100,v/max*100))}%"></i></div><small>${sub}</small></div></div>`}).join('')}
function metricValue(p,k){return k==='impact'?Number(p.knownHours||0):k==='participation'?Number(p.participationRate||0):Number(p.crossSupportRate||0)}
function render(){const d=state.data,s=d.summary||{},ps=d.programs||[],evs=d.events||[],vs=d.volunteers||[],us=d.unmatched||[],aps=d.availablePrograms||[];const impact=[...ps].sort((a,b)=>b.knownHours-a.knownHours),part=[...ps].sort((a,b)=>b.participationRate-a.participationRate),support=[...ps].sort((a,b)=>b.crossSupportRate-a.crossSupportRate);const leader=impact[0],pleader=part[0],sleader=support[0];const totalEq=ps.reduce((a,p)=>a+Number(p.volunteerCredits||0),0);const range=state.start||state.end?`${state.start||'Beginning'} – ${state.end||'Present'}`:'All synchronized dates';const ready=(s.classificationRate||0)>=95;
app.innerHTML=`<div class="appShell"><aside class="sidebar"><div class="brand"><img src="/boosters-logo.png" alt="Miamisburg Band and Guard Boosters logo"><div><strong>Volunteer Impact</strong><span>Program Scoreboard</span></div></div><nav><a href="#scoreboard" class="active">Scoreboard</a><a href="#standings">Standings</a><a href="#events">Events</a><a href="#volunteers">Volunteer Detail</a><a href="#admin">Admin</a></nav><div class="sideCallout"><span>ONE BOOSTER.</span><strong>Every hour helps every program.</strong><small>Celebrate the groups stepping up—and make the gaps impossible to ignore.</small></div><div class="version">v0.4.0 public scoreboard</div></aside><main>
<section class="hero" id="scoreboard"><div class="heroTop"><div><div class="eyebrow">MIAMISBURG BAND &amp; GUARD BOOSTERS</div><h1>Volunteer Impact Scoreboard</h1><p>See the time our families are giving, which programs are stepping up, and where more hands are needed.</p></div><div class="heroActions"><button class="ghost" id="syncContacts">Sync Contacts</button><button id="syncAll">Sync All</button></div></div><div class="filterBar"><div class="filterText"><span>Showing</span><strong>${esc(range)}</strong></div><label>Start<input id="startDate" type="date" value="${esc(state.draftStart)}"></label><label>End<input id="endDate" type="date" value="${esc(state.draftEnd)}"></label><button id="applyFilter">Apply</button><button class="ghost" id="clearFilter">Clear</button></div></section><div id="flash"></div>
<section class="impactStrip">${metric('⏱','Volunteer Hours Contributed',`${fmt(s.hoursFilled)} hrs`,`${fmt(totalEq)} volunteer equivalents represented`)}${metric('✓','Volunteer Need Coverage',pct(s.fillRate),`${fmt(s.hoursRemaining)} hours still available`)}${metric('🏆','Total Impact Leader',leader?.name||'—',leader?`${fmt(leader.knownHours)} credited hours`:'No credited hours yet',true)}${metric('★','Participation Leader',pleader?.name||'—',pleader?`${pct(pleader.participationRate)} participation strength`:'No participation data yet')}</section>
<section class="leaderGrid" id="standings"><div class="leaderboard impactBoard">${boardHead('TOTAL IMPACT','Which program is carrying the most volunteer workload?','Credited hours are split proportionally when a volunteer represents multiple programs.')}<div class="rankList">${rankRows(ps,'impact')}</div></div><div class="leaderboard participationBoard">${boardHead('PARTICIPATION STRENGTH','Which program has the broadest volunteer engagement?','Each caregiver counts separately. Multi-program caregivers are fractionally weighted in both eligible and participating totals.')}<div class="rankList">${rankRows(ps,'participation')}</div></div></section>
<section class="storyGrid"><div class="storyCard coverage"><div class="storyHead"><div><span class="kicker">ORGANIZATION NEED</span><h2>${pct(s.fillRate)} of available volunteer hours are covered</h2></div><div class="bigRing" style="--ring:${Math.min(100,s.fillRate||0)*3.6}deg"><strong>${pct(s.fillRate)}</strong><span>covered</span></div></div><div class="coverageBar"><i style="width:${Math.min(100,s.fillRate||0)}%"></i></div><div class="coverageStats"><span><b>${fmt(s.hoursNeeded)}</b> hrs available</span><span><b>${fmt(s.hoursFilled)}</b> hrs filled</span><span><b>${fmt(s.hoursRemaining)}</b> hrs still need hands</span></div></div><div class="storyCard oneBooster"><div class="storyHead"><div><span class="kicker">ONE BOOSTER SUPPORT</span><h2>${ready&&sleader?`${esc(sleader.name)} leads cross-program support`:'Classify events to unlock cross-program standings'}</h2></div><span class="statusPill ${ready?'ready':'setup'}">${ready?'LIVE':'SETUP NEEDED'}</span></div>${ready?`<div class="rankList compact">${rankRows(ps,'support')}</div>`:`<div class="setupMessage"><strong>${pct(s.classificationRate)} of volunteer hours have a classified event.</strong><p>Set each event to a program or Booster-Wide below. The scoreboard will then show which programs volunteer outside their own silo.</p></div>`}</div></section>
<section class="gapSection"><div class="sectionTitle"><span class="kicker">CLOSING THE GAP</span><h2>What would it take to move up?</h2><p>Friendly pressure, backed by the actual numbers.</p></div><div class="gapGrid">${impact.map((p,i)=>i===0?`<div class="gapCard leaderGap"><span>Current #1</span><strong>${esc(p.name)}</strong><em>${fmt(p.knownHours)} hrs</em></div>`:`<div class="gapCard"><span>#${i+1} ${esc(p.name)}</span><strong>${fmt(Math.max(0,impact[i-1].knownHours-p.knownHours))} more hrs</strong><em>to catch ${esc(impact[i-1].name)}</em></div>`).join('')}</div></section>
<section class="panel" id="events"><div class="sectionHead"><div><span class="kicker">EVENTS</span><h2>Volunteer opportunities &amp; program affiliation</h2><p>Event affiliation does not change hour credit. It only measures whether families are supporting their own program or helping across the organization.</p></div><span class="classification">${pct(s.classificationRate)} classified</span></div><div class="eventGrid">${evs.map(ev=>`<div class="eventCard"><div class="eventDate">${dte(ev.eventDate)}</div><h3>${esc(ev.title)}</h3><p>${esc(ev.location||'Location not listed')}</p><div class="eventNumbers"><span><b>${fmt(ev.hoursFilled)}</b> filled hrs</span><span><b>${fmt(Math.max(0,ev.hoursNeeded-ev.hoursFilled))}</b> open hrs</span></div><label class="eventSelect">Affiliation<select class="eventAff" data-id="${ev.id}"><option value="">Unclassified</option><option value="Booster-Wide" ${ev.affiliation==='Booster-Wide'?'selected':''}>Booster-Wide</option>${aps.map(x=>`<option value="${esc(x)}" ${ev.affiliation===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label></div>`).join('')}</div></section>
<section class="panel" id="volunteers"><div class="sectionHead"><div><span class="kicker">DETAIL</span><h2>Volunteer Hours</h2><p>Administrative detail supporting the public scoreboard.</p></div><span>${vs.length} volunteers shown</span></div><div class="tableWrap"><table><thead><tr><th>Volunteer</th><th>Program attribution</th><th>Known hours</th><th>Allocation</th></tr></thead><tbody>${vs.map(v=>{const pp=programsOf(v.attribution);return `<tr><td><div class="person"><span class="avatar">${initials(v.name)}</span><div><strong>${esc(v.name)}</strong><small>${esc(v.email||'No email')}</small></div></div></td><td><div class="badges">${pp.length?pp.map(x=>`<span>${esc(x)}</span>`).join(''):'<span class="unmatchedBadge">Unmatched</span>'}</div></td><td><b>${fmt(v.knownHours)}</b> hrs</td><td>${pp.length?pp.map(x=>`<small class="allocation">${esc(x)}: ${fmt(v.knownHours/pp.length)} hrs</small>`).join(''):'—'}</td></tr>`}).join('')}</tbody></table></div></section>
<section class="adminGrid" id="admin"><div class="panel"><div class="sectionHead"><div><span class="kicker">ADMIN</span><h2>Unmatched volunteers</h2><p>Assign a program once and future signups using the same email will inherit it.</p></div><span class="warningCount">${us.length}</span></div>${us.length?us.map(u=>unmatchedRow(u,aps)).join(''):'<div class="empty">Everyone is attributed.</div>'}</div><div class="panel"><div class="sectionHead"><div><span class="kicker">SYSTEM</span><h2>Scoreboard health</h2></div></div><div class="healthList"><div><span>Roster contacts</span><b>${s.uniqueContactEmails||0}</b></div><div><span>Matched volunteers</span><b>${s.matchedVolunteers||0}</b></div><div><span>Manual overrides</span><b>${s.manualOverrideEmails||0}</b></div><div><span>Unmatched volunteers</span><b>${s.unmatchedVolunteers||0}</b></div><div><span>Event classification</span><b>${pct(s.classificationRate)}</b></div><div><span>Last signup sync</span><b>${s.lastSyncAt?new Date(s.lastSyncAt).toLocaleString():'Never'}</b></div></div></div></section>
</main></div>`;bind()}
function metric(icon,label,value,sub,gold=false){return `<div class="metric ${gold?'gold':''}"><span class="metricIcon">${icon}</span><div><small>${label}</small><strong>${esc(value)}</strong><p>${esc(sub)}</p></div></div>`}
function boardHead(k,t,x){return `<div class="boardHeader"><span class="kicker">${k}</span><h2>${t}</h2><p>${x}</p></div>`}
function unmatchedRow(u,aps){const editing=state.editing===u.email;return `<div class="unmatchedRow"><div><strong>${esc(u.name)}</strong><small>${esc(u.email||'No email')} · ${fmt(u.knownHours)} hrs</small></div>${editing?`<div class="assignBox"><div class="checks">${aps.map(p=>`<label><input type="checkbox" class="programCheck" value="${esc(p)}" ${state.selected.has(p)?'checked':''}>${esc(p)}</label>`).join('')}</div><div><button class="saveOverride" data-email="${esc(u.email)}" data-name="${esc(u.name)}">Save</button> <button class="ghost cancelOverride">Cancel</button></div></div>`:`<button class="assignBtn" data-email="${esc(u.email||'')}" ${u.email?'':'disabled'}>Assign Program</button>`}</div>`}
function flash(text,bad=false){const el=document.getElementById('flash');if(el)el.innerHTML=`<div class="notice ${bad?'error':'success'}">${esc(text)}</div>`}
function bind(){document.getElementById('startDate').addEventListener('change',e=>state.draftStart=e.target.value);document.getElementById('endDate').addEventListener('change',e=>state.draftEnd=e.target.value);document.getElementById('applyFilter').onclick=()=>{if(state.draftStart&&state.draftEnd&&state.draftStart>state.draftEnd)return flash('Start date cannot be after end date.',true);state.start=state.draftStart;state.end=state.draftEnd;load()};document.getElementById('clearFilter').onclick=()=>{state.start=state.end=state.draftStart=state.draftEnd='';load()};document.getElementById('syncAll').onclick=async()=>{try{flash('Syncing…');const d=await post('/api/sync');await load();setTimeout(()=>flash(d.message),50)}catch(e){flash(e.message,true)}};document.getElementById('syncContacts').onclick=async()=>{try{flash('Syncing contacts…');const d=await post('/api/contacts/sync');await load();setTimeout(()=>flash(d.message),50)}catch(e){flash(e.message,true)}};document.querySelectorAll('.eventAff').forEach(el=>el.addEventListener('change',async e=>{try{const d=await post('/api/events/affiliation',{eventId:Number(e.target.dataset.id),affiliation:e.target.value});await load();setTimeout(()=>flash(d.message),50)}catch(x){flash(x.message,true)}}));document.querySelectorAll('.assignBtn').forEach(b=>b.onclick=()=>{state.editing=b.dataset.email;state.selected=new Set();render()});document.querySelectorAll('.programCheck').forEach(c=>c.onchange=()=>{c.checked?state.selected.add(c.value):state.selected.delete(c.value)});document.querySelectorAll('.cancelOverride').forEach(b=>b.onclick=()=>{state.editing=null;state.selected=new Set();render()});document.querySelectorAll('.saveOverride').forEach(b=>b.onclick=async()=>{if(!state.selected.size)return flash('Select at least one program.',true);try{const d=await post('/api/attribution/override',{email:b.dataset.email,name:b.dataset.name,programs:[...state.selected]});state.editing=null;state.selected=new Set();await load();setTimeout(()=>flash(d.message),50)}catch(e){flash(e.message,true)}})}
load();
